# filename: tools/seed.py
import asyncio, json, os, time
from decimal import Decimal

import aioboto3

ENDPOINT = os.getenv("AWS_ENDPOINT_URL_DYNAMODB", "http://dynamodb-local:8000")
TABLE = os.getenv("FEATURE_TABLE", "card_features")
NOW = int(time.time())


def card(token, count=1, avg="42.10", devices=("dev_1", "dev_2"), blocked=False, age_s=0):
    return {"card_token": token, "txn_count_5m": count, "avg_amount_30d": Decimal(avg),
            "known_devices": list(devices), "blocked": blocked, "updated_at": NOW - age_s}


PLANTED = [
    card("tok_normal"),
    card("tok_blocked", blocked=True),
    card("tok_velocity", count=10),
    card("tok_boundary", count=9),
    card("tok_stale", count=11, age_s=7200),      # older than stale_after_s (3600)
    card("tok_newdev", devices=("dev_1",)),
    card("tok_knowndev", devices=("dev_1", "dev_9")),
]


async def main() -> None:
    async with aioboto3.Session().resource("dynamodb", endpoint_url=ENDPOINT) as ddb:
        try:
            await ddb.create_table(
                TableName=TABLE, BillingMode="PAY_PER_REQUEST",
                KeySchema=[{"AttributeName": "card_token", "KeyType": "HASH"}],
                AttributeDefinitions=[{"AttributeName": "card_token", "AttributeType": "S"}])
        except ddb.meta.client.exceptions.ResourceInUseException:
            pass
        table = await ddb.Table(TABLE)
        total = 0
        async with table.batch_writer() as batch:
            for c in PLANTED:
                await batch.put_item(Item=c)
                total += 1
            path = os.getenv("CARDS_FILE")
            if path:
                with open(path) as f:
                    for line in f:
                        c = json.loads(line)
                        await batch.put_item(Item={
                            "card_token": c["token"], "txn_count_5m": 0, "blocked": False,
                            "avg_amount_30d": Decimal(c["avg"]), "known_devices": c["devices"],
                            "updated_at": NOW})
                        total += 1
        print(f"seeded {total} cards into {TABLE}")


asyncio.run(main())
